	begin
		if rising_edge(CLK) then
			case WINDOW_TYPE is
				when "00" => VALUE <= "0001000000000000";
				when "01" => VALUE <= kaiser(i);
				when "10" => VALUE <= hann(i);
				when "11" => VALUE <= flattop(i);
				when others => VALUE <= (others => '0');
